// Minimal, forgiving .xlsx reader for Shopee exports.
//
// Shopee's files are generated by streaming writers that use inline strings,
// empty cells and rich text in ways some libraries reject ("Unsupported inline
// string"). This reader only needs values, so it reads the zip with the
// browser's DecompressionStream and the sheet XML with plain string scanning.
// Works in the browser and in Node 18+.

export type XlsxCell = string | number | boolean | null;
export type XlsxSheet = { name: string; rows: XlsxCell[][] };

type ZipEntry = { name: string; method: number; offset: number; compressedSize: number };

function readZipEntries(bytes: Uint8Array): Map<string, ZipEntry> {
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  // End of central directory: signature 0x06054b50, within the last 64 KB.
  let eocd = -1;
  for (let i = bytes.length - 22; i >= Math.max(0, bytes.length - 65557); i--) {
    if (view.getUint32(i, true) === 0x06054b50) {
      eocd = i;
      break;
    }
  }
  if (eocd < 0) {
    throw new Error(
      "This is not an .xlsx file. In Excel, use File → Save As → Excel Workbook (.xlsx), or export CSV."
    );
  }
  const count = view.getUint16(eocd + 10, true);
  let pointer = view.getUint32(eocd + 16, true);
  const entries = new Map<string, ZipEntry>();
  const decoder = new TextDecoder();
  for (let n = 0; n < count; n++) {
    if (view.getUint32(pointer, true) !== 0x02014b50) break;
    const method = view.getUint16(pointer + 10, true);
    const compressedSize = view.getUint32(pointer + 20, true);
    const nameLength = view.getUint16(pointer + 28, true);
    const extraLength = view.getUint16(pointer + 30, true);
    const commentLength = view.getUint16(pointer + 32, true);
    const offset = view.getUint32(pointer + 42, true);
    const name = decoder.decode(bytes.subarray(pointer + 46, pointer + 46 + nameLength));
    entries.set(name.replace(/^\/+/, ""), { name, method, offset, compressedSize });
    pointer += 46 + nameLength + extraLength + commentLength;
  }
  return entries;
}

async function inflate(data: Uint8Array): Promise<Uint8Array> {
  const stream = new Blob([data as BlobPart]).stream().pipeThrough(new DecompressionStream("deflate-raw"));
  return new Uint8Array(await new Response(stream).arrayBuffer());
}

// Some writers (e.g. .NET Open XML SDK, BigSeller-style exports) prefix every
// tag, as in <x:sheet> or <x:row>. Drop tag prefixes so one parser fits all.
function stripTagPrefixes(xml: string): string {
  return xml.replace(/<(\/?)[A-Za-z_][\w.-]*:(?=[A-Za-z_])/g, "<$1");
}

async function readEntry(bytes: Uint8Array, entry: ZipEntry): Promise<string> {
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const nameLength = view.getUint16(entry.offset + 26, true);
  const extraLength = view.getUint16(entry.offset + 28, true);
  const start = entry.offset + 30 + nameLength + extraLength;
  const raw = bytes.subarray(start, start + entry.compressedSize);
  let data: Uint8Array;
  if (entry.method === 0) data = raw;
  else if (entry.method === 8) data = await inflate(raw);
  else throw new Error("Unsupported compression in this .xlsx file.");
  return stripTagPrefixes(new TextDecoder().decode(data));
}

function decodeXml(value: string): string {
  return value.replace(/&(#x[0-9a-f]+|#\d+|amp|lt|gt|quot|apos);/gi, (_, code: string) => {
    const lower = code.toLowerCase();
    if (lower === "amp") return "&";
    if (lower === "lt") return "<";
    if (lower === "gt") return ">";
    if (lower === "quot") return '"';
    if (lower === "apos") return "'";
    const n = lower.startsWith("#x") ? parseInt(lower.slice(2), 16) : parseInt(lower.slice(1), 10);
    return Number.isFinite(n) ? String.fromCodePoint(n) : "";
  });
}

function attr(tag: string, name: string): string | null {
  const match = new RegExp("\\s" + name + "\\s*=\\s*(\"([^\"]*)\"|'([^']*)')").exec(tag);
  return match ? decodeXml(match[2] ?? match[3] ?? "") : null;
}

// Text of all <t> runs (plain or rich text), ignoring phonetic hints.
function textRuns(xml: string): string {
  const cleaned = xml.replace(/<rPh\b[\s\S]*?<\/rPh>/g, "");
  let out = "";
  const re = /<t(?:\s[^>]*)?>([\s\S]*?)<\/t>/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(cleaned))) out += decodeXml(m[1]);
  return out;
}

function columnIndex(ref: string | null, fallback: number): number {
  const letters = ref ? /^[A-Z]+/i.exec(ref)?.[0] : null;
  if (!letters) return fallback;
  let n = 0;
  for (const ch of letters.toUpperCase()) n = n * 26 + (ch.charCodeAt(0) - 64);
  return n - 1;
}

function parseSheet(xml: string, shared: string[]): XlsxCell[][] {
  const rows: XlsxCell[][] = [];
  const rowRe = /<row\b([^>]*?)(?:\/>|>([\s\S]*?)<\/row>)/g;
  let rowMatch: RegExpExecArray | null;
  while ((rowMatch = rowRe.exec(xml))) {
    const rowNumber = Number(attr(rowMatch[1], "r")) || rows.length + 1;
    const cells: XlsxCell[] = [];
    const body = rowMatch[2] || "";
    const cellRe = /<c\b([^>]*?)(?:\/>|>([\s\S]*?)<\/c>)/g;
    let cellMatch: RegExpExecArray | null;
    while ((cellMatch = cellRe.exec(body))) {
      const tag = cellMatch[1];
      const inner = cellMatch[2] || "";
      const col = columnIndex(attr(tag, "r"), cells.length);
      const type = attr(tag, "t") || "n";
      const v = /<v(?:\s[^>]*)?>([\s\S]*?)<\/v>/.exec(inner)?.[1];
      let value: XlsxCell = null;
      if (type === "s") value = v != null ? shared[Number(v)] ?? "" : "";
      else if (type === "inlineStr") value = textRuns(inner);
      else if (type === "str" || type === "d") value = v != null ? decodeXml(v) : textRuns(inner);
      else if (type === "b") value = v === "1";
      else if (type === "e") value = null;
      else if (v != null && v !== "") {
        const n = Number(v);
        value = Number.isFinite(n) ? n : decodeXml(v);
      }
      cells[col] = value;
    }
    for (let i = 0; i < cells.length; i++) if (cells[i] === undefined) cells[i] = null;
    rows[rowNumber - 1] = cells;
  }
  for (let i = 0; i < rows.length; i++) if (!rows[i]) rows[i] = [];
  return rows;
}

function resolveTarget(target: string): string {
  if (target.startsWith("/")) return target.slice(1);
  const parts = ("xl/" + target).split("/");
  const out: string[] = [];
  for (const part of parts) {
    if (part === "..") out.pop();
    else if (part && part !== ".") out.push(part);
  }
  return out.join("/");
}

export async function readXlsx(input: ArrayBuffer | Uint8Array): Promise<XlsxSheet[]> {
  const bytes = input instanceof Uint8Array ? input : new Uint8Array(input);
  const entries = readZipEntries(bytes);
  const lower = new Map(Array.from(entries, ([name, entry]) => [name.toLowerCase(), entry]));
  const read = async (path: string) => {
    const entry = entries.get(path) || lower.get(path.toLowerCase());
    return entry ? readEntry(bytes, entry) : null;
  };

  const workbook = await read("xl/workbook.xml");
  if (!workbook) throw new Error("This .xlsx file has no workbook. Re-download it from Shopee.");

  const sharedXml = await read("xl/sharedStrings.xml");
  const shared: string[] = [];
  if (sharedXml) {
    const siRe = /<si\b[^>]*?(?:\/>|>([\s\S]*?)<\/si>)/g;
    let m: RegExpExecArray | null;
    while ((m = siRe.exec(sharedXml))) shared.push(textRuns(m[1] || ""));
  }

  const relsXml = (await read("xl/_rels/workbook.xml.rels")) || "";
  const targets = new Map<string, string>();
  const relRe = /<Relationship\b([^>]*)\/?>/g;
  let rel: RegExpExecArray | null;
  while ((rel = relRe.exec(relsXml))) {
    const id = attr(rel[1], "Id");
    const target = attr(rel[1], "Target");
    if (id && target) targets.set(id, resolveTarget(target));
  }

  const sheets: XlsxSheet[] = [];
  const sheetRe = /<sheet\b([^>]*)\/?>/g;
  let sheet: RegExpExecArray | null;
  let index = 0;
  while ((sheet = sheetRe.exec(workbook))) {
    index += 1;
    const name = attr(sheet[1], "name") || "Sheet" + index;
    const relId = attr(sheet[1], "r:id") || /\s[\w.-]+:id\s*=\s*["']([^"']+)["']/.exec(sheet[1])?.[1] || null;
    const path = (relId && targets.get(relId)) || "xl/worksheets/sheet" + index + ".xml";
    const xml = await read(path);
    if (xml) sheets.push({ name, rows: parseSheet(xml, shared) });
  }
  // Workbook didn't point to readable sheets: read every worksheet in the zip.
  if (!sheets.length) {
    const paths = Array.from(entries.keys())
      .filter((n) => /^xl\/worksheets\/[^/]+\.xml$/i.test(n))
      .sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));
    for (const path of paths) {
      const xml = await read(path);
      if (xml) sheets.push({ name: path.split("/").pop()!.replace(/\.xml$/i, ""), rows: parseSheet(xml, shared) });
    }
  }
  return sheets;
}
